// Combine all GitHub data into a structured prompt for Claude

const commits = $input.all()[0]?.json || [];
const issues = $input.all()[1]?.json || [];
const prs = $input.all()[2]?.json || [];

const repoOwner = commits[0]?.repoOwner || $json.repoOwner;
const repoName = commits[0]?.repoName || $json.repoName;
const language = commits[0]?.language || 'en';
const destination = commits[0]?.destination || 'slack';
const webhookUrl = commits[0]?.webhookUrl || '';
const emailTo = commits[0]?.emailTo || '';

// Format commits
const commitList = commits.map(c => ({
  hash: c.sha?.substring(0, 7),
  message: c.commit?.message?.split('\n')[0],
  author: c.commit?.author?.name,
  date: c.commit?.author?.date?.substring(0, 10)
})).slice(0, 30);

// Format merged PRs
const prList = prs
  .filter(p => new Date(p.merged_at) > new Date(Date.now() - 7 * 24 * 60 * 60 * 1000))
  .map(p => ({
    number: p.number,
    title: p.title,
    author: p.user?.login,
    merged_at: p.merged_at?.substring(0, 10)
  }));

// Format closed issues
const issueList = issues
  .filter(i => !i.pull_request)
  .map(i => ({
    number: i.number,
    title: i.title,
    state: i.state,
    closed_at: i.closed_at?.substring(0, 10)
  }));

const dataForPrompt = {
  repoOwner,
  repoName,
  language,
  destination,
  webhookUrl,
  emailTo,
  stats: {
    totalCommits: commits.length,
    totalPRs: prList.length,
    totalClosedIssues: issueList.length,
    uniqueAuthors: [...new Set(commitList.map(c => c.author).filter(Boolean))].length
  },
  recentCommits: commitList.slice(0, 20),
  mergedPRs: prList,
  closedIssues: issueList
};

return [{ json: dataForPrompt }];

